#pragma once

// Hand-written FFI types for the syscall boundary.
// These must match the Rust repr(C) layout from groundhog-xdr.
//
// These were previously generated by cbindgen from the contract_types crate.
// cbindgen 0.29.2 has a bug where it emits `(Constant)._0` for enum
// discriminants derived from Rust newtype struct associated constants
// (e.g. `AuthClaimType::kSourceAddressAuthData.0 as i32`). cbindgen
// correctly flattens the newtype to a C++ typedef (`using AuthClaimType =
// int32_t`), but then still emits the `.0` field access as `._0`, producing
// invalid C++. There is no config workaround of which I am aware.
// Rather than post-processing the output, we maintain these types by hand.

#include <type_traits>
#include <utility>

#include "auth_claim.hh"
#include "hogd/base/types.h"
#include "types.hh"

namespace hogd::generated {

// NOLINTBEGIN(readability-identifier-naming)

union PublicKey {
  enum Tag : int32_t {
    PublicKey_Ed25519 = std::to_underlying(hogd::PublicKey::Ed25519)
  };

  struct PublicKey_Ed25519_Body {
    Tag tag;
    Ed25519PublicKey ed25519;
    static_assert(std::is_trivially_copyable_v<Ed25519PublicKey>);
  };

  struct {
    Tag tag;
  };
  PublicKey_Ed25519_Body ed25519;
};

static_assert(std::is_trivially_copyable_v<PublicKey>);
static_assert(sizeof(PublicKey) == sizeof(hogd::PublicKey));

struct PubkeyAccountPreimage {
  PublicKey pubkey;
  uint64_t nonce;
};

static_assert(std::is_trivially_copyable_v<PubkeyAccountPreimage>);
static_assert(sizeof(PubkeyAccountPreimage) ==
              sizeof(hogd::PubkeyAccountPreimage));

union AuthClaim {
  enum Tag : int32_t {
    AuthClaim_kSourceAddressAuthData =
        std::to_underlying(hogd::AuthClaimType::kSourceAddressAuthData),
    AuthClaim_kPubkeySignature =
        std::to_underlying(hogd::AuthClaimType::kPubkeySignature),
  };

  struct AuthClaim_kSourceAddressAuthData_Body {
    Tag tag;
    using source_claim_t = std::remove_cvref_t<
        decltype(std::declval<hogd::AuthClaim>().source_address_claim())>;
    static_assert(std::is_trivially_copyable_v<source_claim_t>);
    source_claim_t source_address_claim;
  };

  struct AuthClaim_kPubkeySignature_Body {
    Tag tag;
    PubkeyAccountPreimage pubkey_preimage;
  };

  struct {
    Tag tag;
  };
  AuthClaim_kSourceAddressAuthData_Body k_source_address_auth_data;
  AuthClaim_kPubkeySignature_Body k_pubkey_signature;
};

static_assert(std::is_trivially_copyable_v<AuthClaim>);
static_assert(sizeof(AuthClaim) == sizeof(hogd::AuthClaim));

// NOLINTEND(readability-identifier-naming)

} // namespace hogd::generated
